//###########################################################
// EMA for color states
EMA_PERIOD = 20;

//###########################################################
// Color States:
//   green  = HYG above EMA for 2+ consecutive days (risk on)
//   blue   = single day break above EMA (recovery signal)
//   red    = HYG below EMA for 2+ consecutive days (risk off)
//   yellow = single day break below EMA (caution)

//###########################################################
closes = null; // cached EoD closes for EMA and color states base

states = null; // whole array of historic color states

ema = null; // locally cached EMA array


//###########################################################
export var initEMA = function(data) {
  var count, i, j, k, l, prev, ref, ref1, ref2, seedIdx, sum;
  log("initEMA");
  if (!(Array.isArray(data) && data.length > 0)) {
    return;
  }
  log("we also have data to initialize...");
  closes = data;
  ema = new Array(data.length).fill(null);
  // SMA seed from first `EMA_PERIOD` valid values
  sum = 0;
  count = 0;
  seedIdx = -1;
  for (i = j = 0, ref = data.length; (0 <= ref ? j < ref : j > ref); i = 0 <= ref ? ++j : --j) {
    if (data[i] == null) {
      continue;
    }
    sum += data[i];
    count++;
    if (count === EMA_PERIOD) {
      seedIdx = i;
      ema[i] = sum / EMA_PERIOD;
      break;
    }
  }
  if (seedIdx < 0) {
    return mapColorStates();
  }
  k = 2 / (EMA_PERIOD + 1);
  for (i = l = ref1 = seedIdx + 1, ref2 = data.length; (ref1 <= ref2 ? l < ref2 : l > ref2); i = ref1 <= ref2 ? ++l : --l) {
    prev = ema[i - 1];
    if ((data[i] != null) && (prev != null)) {
      ema[i] = data[i] * k + prev * (1 - k);
    } else {
      ema[i] = prev;
    }
  }
  return mapColorStates();
};

//###########################################################
mapColorStates = function() {
  var aboveCount, belowCount, i, j, ref;
  log("mapColorStates");
  if (ema == null) {
    return;
  }
  log("we have an ema - good...");
  states = new Array(closes.length).fill(null);
  aboveCount = 0;
  belowCount = 0;
  for (i = j = 0, ref = closes.length; (0 <= ref ? j < ref : j > ref); i = 0 <= ref ? ++j : --j) {
    if (!((closes[i] != null) && (ema[i] != null))) {
      continue;
    }
    if (closes[i] > ema[i]) {
      aboveCount++;
      belowCount = 0;
      states[i] = aboveCount >= 2 ? "green" : "blue";
    } else {
      belowCount++;
      aboveCount = 0;
      states[i] = belowCount >= 2 ? "red" : "yellow";
    }
  }
};

//###########################################################
export var getAllColorStates = function() {
  return states;
};

//###########################################################
export var getCurrentPriceState = function(price) {
  var lastClose, lastEMA, lastState;
  log("getCurrentPriceState");
  if (ema == null) {
    return "";
  }
  lastEMA = ema[ema.length - 1];
  lastState = states[states.length - 1];
  lastClose = closes[closes.length - 1];
  olog({lastEMA, lastState, lastClose, price});
  // if price is exactly the same, then it most probably is the last close
  if (lastClose === price) {
    return lastState;
  }
  // check how the current price adds to the situation and return resulting state
  if (price > lastEMA) {
    if (lastState === "green") {
      return "green";
    }
    if (lastState === "blue") {
      return "green";
    }
    if (lastState === "yellow") {
      return "blue";
    }
    if (lastState === "red") {
      return "blue";
    }
  } else {
    if (lastState === "red") {
      return "red";
    }
    if (lastState === "yellow") {
      return "red";
    }
    if (lastState === "blue") {
      return "yellow";
    }
    if (lastState === "green") {
      return "yellow";
    }
  }
};
